import torch
from torch.export.unflatten import InterpreterModule
class M(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.a = torch.nn.Linear(8, 4)
        self.b = torch.nn.Linear(4, 2)
    def forward(self, x):
        return self.b(self.a(x))
m = M()
ep = torch.export.export(m, (torch.randn(2, 8),))
unflat = torch.export.unflatten(ep)
print(hasattr(unflat, 'a'))

